(function(w){w.HOMEWORK_SET_DATA=w.HOMEWORK_SET_DATA||{};w.HOMEWORK_SET_DATA["unit31-trap-c5-advanced-1"]={"id":"unit31-trap-c5-advanced-1","unitId":"3-1","chapterIds":["3-1"],"unitType":"advanced","group":"3-1단원 · 선지 변형 유형 · 조건","name":"심화 1","level":"심화","revision":1,"originPage":"unit31","shuffleQuestions":true,"timedMode":"question","isTypePractice":true,"practiceMode":"trap","practiceCategory":"조건","parts":[{"name":"U31-P09-03-S1 · 조건","items":[{"paragraphCount":1,"readingLabel":"9문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 9문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 9문단]\n프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다. 그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다. 어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다. 사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"기술을 익히려면 이론도 배우고 실습도 해야 한다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.”\n9문단에서 확인할 수 있어요.","evidence":{"title":"기술에는 이론과 실습이 필요하다.","statement":"기술을 익히려면 이론도 배우고 실습도 해야 한다.","explanation":"기술을 익히려면 이론도 배우고 실습도 해야 한다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.”\n9문단에서 확인할 수 있어요.","valid":["R09:3"],"sources":[{"id":"R09","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"9문단","sentences":[{"id":"R09:1","text":"프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.","paragraph":0,"memberIds":["R09:1"],"topic":"프롬은 현대인이 사랑을 배울 필요가 없다고 생각하는 이유를, 앞의 세 가지 태도로 정리한다."},{"id":"R09:2","text":"그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.","paragraph":0,"memberIds":["R09:2"],"topic":"그러나 프롬은 이렇게 말한다. 사랑은 흔히 말하는 것처럼 즐겁고 들뜬 감정이 아니다. 끊임없이 갈고닦아야(연마해야) 하는 기술이다."},{"id":"R09:3","text":"어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.","paragraph":0,"memberIds":["R09:3"],"topic":"어떤 기술이든 익히려면 그 기술을 이론으로 배우고, 직접 해 보며 연습해야(실습해야) 한다."},{"id":"R09:4","text":"사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.","paragraph":0,"memberIds":["R09:4"],"topic":"사랑의 기술도 마찬가지다. 익히려면 성숙한 사랑이 무엇인지, 그런 진짜 사랑을 하려면 어떻게 해야 하는지를 배워야 한다. 그리고 배운 그대로 실천해야 한다."}]}]},"id":"U31-P09-03-S1","type":"mc","sent":"9문단의 내용과 맞는 설명은?","options":["기술을 익히려면 이론만 배우면 된다. 실습은 필요하지 않다.","프롬은 현대인이 사랑을 배우고 훈련해서 어떤 성과를 거두었는지 세 가지 태도로 설명한다.","기술을 익히려면 이론도 배우고 실습도 해야 한다.","프롬은 사랑이 저절로 완성되는 감정이라고 본다. 배우거나 연습할 필요가 없다는 뜻이다.","사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 외우기만 하면 된다."],"answer":"기술을 익히려면 이론도 배우고 실습도 해야 한다.","choiceReviews":{"기술을 익히려면 이론도 배우고 실습도 해야 한다.":{"reason":"기술을 익히려면 이론도 배우고 실습도 해야 한다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.”\n9문단에서 확인할 수 있어요.","edits":[]},"기술을 익히려면 이론만 배우면 된다. 실습은 필요하지 않다.":{"reason":"바르게 고치면: 기술을 익히려면 이론도 배우고 실습도 해야 한다.\n기술을 익히려면 이론도 배우고 실습도 해야 한다.\n근거: “어떤 기술을 익히기 위해서는 그 기술에 대해서 이론적으로 배우고 실습해야 한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":9,"end":33,"before":"이론만 배우면 된다. 실습은 필요하지 않다.","after":"이론도 배우고 실습도 해야 한다."}]},"프롬은 현대인이 사랑을 배우고 훈련해서 어떤 성과를 거두었는지 세 가지 태도로 설명한다.":{"reason":"바르게 고치면: 프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n프롬은 현대인이 왜 사랑을 배울 필요가 없다고 생각하는지 세 가지 태도로 설명한다.\n근거: “프롬은 현대인이 사랑에 대해서 배울 필요가 없다고 생각하는 이유를 위와 같은 세 가지의 태도로 정리한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":4,"end":9,"before":"현대인이 ","after":"현대인이 왜 "},{"start":13,"end":35,"before":"배우고 훈련해서 어떤 성과를 거두었는지 ","after":"배울 필요가 없다고 생각하는지 "}]},"프롬은 사랑이 저절로 완성되는 감정이라고 본다. 배우거나 연습할 필요가 없다는 뜻이다.":{"reason":"바르게 고치면: 프롬은 사랑도 기술이라고 본다. 계속 배우고 연습해야 한다는 뜻이다.\n프롬은 사랑도 기술이라고 본다. 계속 배우고 연습해야 한다는 뜻이다.\n근거: “그러나 프롬은 사랑이 흔히 말하듯 즐겁고 흥분된 감정이 아니라 끊임없이 연마해야 하는 기술이라고 말한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":4,"end":23,"before":"사랑이 저절로 완성되는 감정이라고 ","after":"사랑도 기술이라고 "},{"start":27,"end":44,"before":"배우거나 연습할 필요가 없다는 ","after":"계속 배우고 연습해야 한다는 "}]},"사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 외우기만 하면 된다.":{"reason":"바르게 고치면: 사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 직접 실천해야 한다.\n사랑의 기술을 익히려면 성숙한 사랑이 무엇인지 배우고 직접 실천해야 한다.\n근거: “사랑의 기술 역시 그것을 익히기 위해서는 성숙한 사랑이 무엇인지, 그리고 그러한 진정한 사랑을 하기 위해서는 어떻게 해야 하는지를 배우고 그대로 실천해야 한다.”\n9문단에서 확인할 수 있어요.","edits":[{"start":30,"end":41,"before":"외우기만 하면 된다.","after":"직접 실천해야 한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"5ea5730841ce2d1f954e31b7780d4381a3b3e6b5eb9ac6cd157ae9cea439aa6f"}]},{"name":"U31-P12-01-S1 · 조건","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"주는 사랑에는 인격적 성숙이 필요하다.","statement":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.","explanation":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","valid":["R12:1"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"id":"U31-P12-01-S1","type":"mc","sent":"12문단의 내용과 맞는 설명은?","options":["다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.","성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.","나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다.","남에게 의지하거나 남을 이용하려는 욕심을 버리지 못해도, 다른 사람에게 사랑을 주는 일을 두려워하지 않는다.","다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다."],"answer":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.","choiceReviews":{"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.":{"reason":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[]},"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.":{"reason":"바르게 고치면: 다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":30,"end":35,"before":"미성숙한 ","after":"성숙한 "}]},"성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.":{"reason":"바르게 고치면: 성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":22,"end":27,"before":"더 키운 ","after":"이겨 낸 "}]},"나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다.":{"reason":"바르게 고치면: 나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":7,"end":23,"before":"다른 사람의 개성을 존중하는 ","after":"자기 자신에게만 빠져 있는 "},{"start":40,"end":49,"before":"모습을 갖추어야 ","after":"모습에서 벗어나야 "}]},"남에게 의지하거나 남을 이용하려는 욕심을 버리지 못해도, 다른 사람에게 사랑을 주는 일을 두려워하지 않는다.":{"reason":"바르게 고치면: 남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n남에게 의지하거나 남을 이용하려는 욕심을 버리지 못하면, 다른 사람에게 사랑을 주는 일을 두려워한다.\n근거: “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":27,"end":32,"before":"못해도, ","after":"못하면, "},{"start":50,"end":60,"before":"두려워하지 않는다.","after":"두려워한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"5feae009a328c85e3d4addf4b2128a8b1666b432de9275f432b8fa48a57805ea"}]},{"name":"U31-P12-05-S1 · 조건","items":[{"paragraphCount":1,"readingLabel":"12문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"진정한 사랑을 하려면 자기 삶에 스스로 만족할 수 있어야 한다. 남에게 의지하거나 남을 지배하고 이용하지 않아도 만족할 수 있어야 한다.\n근거: “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"자기 삶에 만족하는 독립성이 필요하다.","statement":"독립적인 사람은 남에게 의지하거나 남을 마음대로 다루지 않아도 자기 삶에 만족한다.","explanation":"진정한 사랑을 하려면 자기 삶에 스스로 만족할 수 있어야 한다. 남에게 의지하거나 남을 지배하고 이용하지 않아도 만족할 수 있어야 한다.\n근거: “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","valid":["R12:4"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"id":"U31-P12-05-S1","type":"mc","sent":"12문단의 내용과 맞는 설명은?","options":["독립적인 사람은 남에게 의지하거나 남을 마음대로 다루어야만 자기 삶에 만족한다.","독립적인 사람은 남에게 의지하거나 남을 마음대로 다루지 않아도 자기 삶에 만족한다.","다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.","성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.","나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다."],"answer":"독립적인 사람은 남에게 의지하거나 남을 마음대로 다루지 않아도 자기 삶에 만족한다.","choiceReviews":{"독립적인 사람은 남에게 의지하거나 남을 마음대로 다루지 않아도 자기 삶에 만족한다.":{"reason":"진정한 사랑을 하려면 자기 삶에 스스로 만족할 수 있어야 한다. 남에게 의지하거나 남을 지배하고 이용하지 않아도 만족할 수 있어야 한다.\n근거: “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","edits":[]},"독립적인 사람은 남에게 의지하거나 남을 마음대로 다루어야만 자기 삶에 만족한다.":{"reason":"바르게 고치면: 독립적인 사람은 남에게 의지하거나 남을 마음대로 다루지 않아도 자기 삶에 만족한다.\n진정한 사랑을 하려면 자기 삶에 스스로 만족할 수 있어야 한다. 남에게 의지하거나 남을 지배하고 이용하지 않아도 만족할 수 있어야 한다.\n근거: “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":27,"end":33,"before":"다루어야만 ","after":"다루지 않아도 "}]},"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.":{"reason":"바르게 고치면: 다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":30,"end":35,"before":"미성숙한 ","after":"성숙한 "}]},"성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.":{"reason":"바르게 고치면: 성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":22,"end":27,"before":"더 키운 ","after":"이겨 낸 "}]},"나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다.":{"reason":"바르게 고치면: 나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":7,"end":23,"before":"다른 사람의 개성을 존중하는 ","after":"자기 자신에게만 빠져 있는 "},{"start":40,"end":49,"before":"모습을 갖추어야 ","after":"모습에서 벗어나야 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"2c69b947dfb1647bf91f72b7378c64713e499d9d9dbac747cc5e412f6049d9a8"}]},{"name":"U31-P13-01-S1 · 조건","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"관심은 생명과 성장을 향한다.","statement":"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.","explanation":"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","valid":["R13:2","R13:3"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"id":"U31-P13-01-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.","책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.","상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.","상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.","상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다."],"answer":"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.","choiceReviews":{"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.":{"reason":"상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","edits":[]},"상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.":{"reason":"바르게 고치면: 상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":40,"before":"'사랑한다'고 말만 하면 된다. ","after":"상대가 잘 살아가고 성장하도록 "},{"start":44,"end":54,"before":"돌볼 필요는 없다.","after":"돌본다."}]},"책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.":{"reason":"바르게 고치면: 책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.\n책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":31,"before":"것을 외면한다. ","after":"것에 응할 준비가 되어 있다. "},{"start":35,"end":44,"before":"잘했든 잘못했든 ","after":"잘했을 때도, 잘못했을 때도 "},{"start":49,"end":56,"before":"하지 않는다.","after":"한다."}]},"상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":37,"before":"인정하지 않고 없애려 한다.","after":"깊이 이해하고 존중한다."}]},"상대를 존경하는 사람은 상대가 나와 똑같은 모습으로 성장하기를 바란다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n상대를 존경하는 사람은 상대가 자기 개성을 지키며 성장하기를 바란다.\n근거: “존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":17,"end":29,"before":"나와 똑같은 모습으로 ","after":"자기 개성을 지키며 "}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"df6a127de83f28dee9b7b1162917b65d8363c99d33ec49d8e8ec7c3ad403c6f4"}]},{"name":"U31-P13-05-S1 · 조건","items":[{"paragraphCount":1,"readingLabel":"13문단","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 13문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 13문단]\n한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다. 첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다. 만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다. 이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다. 책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다. 세 번째는 ‘존경’이다. 존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다. 존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다. 존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"상대를 존중하는 마음이 없으면, 책임지려는 마음이 상대를 마음대로 하거나 소유하려는 욕심으로 바뀌기 쉽다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","evidence":{"title":"존경이 없으면 책임이 지배가 되기 쉽다.","statement":"상대를 존중하지 않으면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.","explanation":"상대를 존중하는 마음이 없으면, 책임지려는 마음이 상대를 마음대로 하거나 소유하려는 욕심으로 바뀌기 쉽다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","valid":["R13:9"],"sources":[{"id":"R13","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"13문단","sentences":[{"id":"R13:1","text":"한편, 프롬은 성숙한 사랑에는 다음 세 가지 요소가 있다고 하였다.","paragraph":0,"memberIds":["R13:1"],"topic":"또 프롬은 성숙한 사랑에 세 가지 요소가 있다고 했다."},{"id":"R13:2","text":"첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.","paragraph":0,"memberIds":["R13:2"],"topic":"첫째는 '적극적인 관심'이다. 내가 사랑하는 상대가 살아가고 자라는 것(생명과 성장)에 적극적으로 마음을 쓰는 것이다."},{"id":"R13:3","text":"만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.","paragraph":0,"memberIds":["R13:3"],"topic":"어떤 사람이 꽃을 사랑한다고 말하면서, 꽃에 물 주는 것을 잊고 있다고 해 보자. 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다."},{"id":"R13:4","text":"이러한 보호와 관심에는 사랑의 두 번째 요소인 ‘책임’이 포함되어 있다.","paragraph":0,"memberIds":["R13:4"],"topic":"이렇게 보호하고 관심을 갖는 것 안에는 사랑의 두 번째 요소인 '책임'이 들어 있다."},{"id":"R13:5","text":"책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.","paragraph":0,"memberIds":["R13:5"],"topic":"책임은 상대가 무언가를 바랄(요구할) 때 응답할 준비가 되어 있는 것이다. 그리고 상대가 잘한 일도 잘못한 일도 함께하려는 것이다."},{"id":"R13:6","text":"세 번째는 ‘존경’이다.","paragraph":0,"memberIds":["R13:6"],"topic":"세 번째는 '존경'이다."},{"id":"R13:7","text":"존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.","paragraph":0,"memberIds":["R13:7"],"topic":"존경한다는 것은 그 사람만의 독특한 개성을 꿰뚫어 보고(통찰하고) 존중하는 것이다."},{"id":"R13:8","text":"존경은 다른 사람이 그 자신으로서 성장하고 발달하기를 바라는 관심이다.","paragraph":0,"memberIds":["R13:8"],"topic":"존경은 상대가 그 사람 자신으로서(그 사람답게) 자라고 발전하기를 바라는 관심이다."},{"id":"R13:9","text":"존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.","paragraph":0,"memberIds":["R13:9"],"topic":"존경이 빠지면(결여되면), 책임은 쉽게 상대를 내 마음대로 하고 내 것으로 삼으려는 욕심으로 떨어진다(전락한다)."}]}]},"id":"U31-P13-05-S1","type":"mc","sent":"13문단의 내용과 맞는 설명은?","options":["상대를 존중하지 않으면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.","상대를 충분히 존중하면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.","상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.","책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.","상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다."],"answer":"상대를 존중하지 않으면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.","choiceReviews":{"상대를 존중하지 않으면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.":{"reason":"상대를 존중하는 마음이 없으면, 책임지려는 마음이 상대를 마음대로 하거나 소유하려는 욕심으로 바뀌기 쉽다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","edits":[]},"상대를 충분히 존중하면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.":{"reason":"바르게 고치면: 상대를 존중하지 않으면, 책임을 지려던 사람이 상대를 자기 뜻대로 움직이려 하기 쉽다.\n상대를 존중하는 마음이 없으면, 책임지려는 마음이 상대를 마음대로 하거나 소유하려는 욕심으로 바뀌기 쉽다.\n근거: “존경이 결여되면, 책임은 쉽게 상대방을 지배하고 소유하려는 욕망으로 전락한다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":4,"end":14,"before":"충분히 존중하면, ","after":"존중하지 않으면, "}]},"상대에게 적극적으로 관심을 갖는 사람은 '사랑한다'고 말만 하면 된다. 실제로 돌볼 필요는 없다.":{"reason":"바르게 고치면: 상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n상대에게 적극적으로 관심을 갖는 사람은 상대가 잘 살아가고 성장하도록 실제로 돌본다.\n근거: “첫째로 사랑하는 자의 생명과 성장에 대한 ‘적극적인 관심’이다.” “만일 어떤 사람이 자기는 꽃을 사랑한다고 말하였는데 꽃에 물을 주는 것을 잊고 있다면, 우리는 그 사람이 꽃을 사랑한다는 말을 믿지 않을 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":40,"before":"'사랑한다'고 말만 하면 된다. ","after":"상대가 잘 살아가고 성장하도록 "},{"start":44,"end":54,"before":"돌볼 필요는 없다.","after":"돌본다."}]},"책임을 지는 사람은 상대가 필요로 하는 것을 외면한다. 상대가 잘했든 잘못했든 함께하려 하지 않는다.":{"reason":"바르게 고치면: 책임을 지는 사람은 상대가 필요로 하는 것에 응할 준비가 되어 있다. 상대가 잘했을 때도, 잘못했을 때도 함께하려 한다.\n책임은 상대의 필요를 외면하지 않고 응하려는 태도다. 상대의 잘잘못도 함께하려는 뜻을 포함한다.\n근거: “책임은 상대의 요구에 응답할 준비가 되어 있다는 것이며, 더불어 다른 사람의 잘잘못을 함께하려는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":31,"before":"것을 외면한다. ","after":"것에 응할 준비가 되어 있다. "},{"start":35,"end":44,"before":"잘했든 잘못했든 ","after":"잘했을 때도, 잘못했을 때도 "},{"start":49,"end":56,"before":"하지 않는다.","after":"한다."}]},"상대를 존경하는 사람은 상대만의 개성을 인정하지 않고 없애려 한다.":{"reason":"바르게 고치면: 상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n상대를 존경하는 사람은 상대만의 개성을 깊이 이해하고 존중한다.\n근거: “존경한다는 것은 어떤 사람의 독특한 개성을 통찰하고 존중하는 것이다.”\n13문단에서 확인할 수 있어요.","edits":[{"start":22,"end":37,"before":"인정하지 않고 없애려 한다.","after":"깊이 이해하고 존중한다."}]}},"pageSpecificReasons":true,"requiresEvidence":true,"editorSourceVersion":"6ea50f012a56bcd56a1eb0a89a24a9bbf122ad58fb54c51a93b2d4bd050f2dc6"}]},{"name":"U31-E06-S1 · 조건","items":[{"paragraphCount":2,"readingLabel":"12문단 · 새 예시 적용","sourceLabel":"에리히 프롬의 『사랑의 기술』 읽기 · 12문단","passage":"[에리히 프롬의 『사랑의 기술』 읽기 · 12문단]\n주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다. 인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다. 이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다. 타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.\n\n[이해를 돕는 새 예시 · 원문 사례 아님]\n하준은 동료가 다 해 주길 바라거나 자기 기록만 챙기거나 동료를 이용하지 않는다. 자기 플레이에 만족하며 편하게 패스한다.","referenceMode":"visible","disableAutoFocus":true,"originPage":"unit31","skills":["조건"],"why":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","evidence":{"title":"독립적인 선수","statement":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","explanation":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","valid":["R12:2","R12:3","R12:4"],"sources":[{"id":"R12","title":"에리히 프롬의 『사랑의 기술』 읽기","label":"12문단","sentences":[{"id":"R12:1","text":"주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.","paragraph":0,"memberIds":["R12:1"],"topic":"'주는' 사랑을 할 수 있는 사람은 사람됨(인격)이 성숙한 사람이다."},{"id":"R12:2","text":"인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.","paragraph":0,"memberIds":["R12:2"],"topic":"인격이 성숙한 사람은 세 가지를 이겨 낸(극복한) 사람이다. 남에게 기대고 싶어 하는 마음(의존), 나에게만 빠져 있는 마음(나르시시즘), 남의 것을 빼앗아 이용하려는 욕심(착취)이다."},{"id":"R12:3","text":"이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.","paragraph":0,"memberIds":["R12:3"],"topic":"이런 성향들을 이겨 내지 못하면, 사람은 사랑을 주는 것을 두려워한다."},{"id":"R12:4","text":"타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.","paragraph":0,"memberIds":["R12:4"],"topic":"남을 존중하는 진짜 사랑은 내가 독립적인 사람일 때만 할 수 있다. 다시 말해, 남에게 기대거나 남을 마음대로 하고 이용하지 않아도 내 삶에 만족할 수 있을 때만 가능하다."}]}]},"examplePractice":true,"id":"U31-E06-S1","type":"mc","sent":"지문을 바탕으로 새 축구 예시를 바르게 설명한 것은?","options":["하준은 동료를 자기 뜻대로 움직여야만 자기 플레이에 만족한다.","하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.","성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.","나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다."],"answer":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.","requiresEvidence":true,"choiceReviews":{"하준은 동료에게 의지하거나 동료를 이용하지 않아도 자기 플레이에 만족한다.":{"reason":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","edits":[]},"하준은 동료를 자기 뜻대로 움직여야만 자기 플레이에 만족한다.":{"reason":"하준은 동료에게 의지하거나 동료를 이용하지 않아도 만족한다. 남에게 의지하거나 남을 지배하지 않아도 자기 삶에 만족할 때 진정한 사랑이 가능하다는 설명과 닮았다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.” “이러한 성향들을 극복하지 않는 한, 인간은 사랑을 주는 것을 두려워한다.” “타인을 존중하는 진정한 사랑은 내가 독립적인 인간일 경우에만, 다시 말해서 남에게 의존하거나 남을 지배하고 착취하지 않아도 나 자신의 삶에 만족할 수 있을 때만 가능하다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":0,"end":4,"before":"하준은 ","after":"하준은 동료에게 의지하거나 "},{"start":8,"end":21,"before":"자기 뜻대로 움직여야만 ","after":"이용하지 않아도 "}]},"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 미성숙한 사람이다.":{"reason":"다른 사람에게 사랑을 베풀 수 있는 사람은 인격적으로 성숙한 사람이다.\n근거: “주는 행위로서의 사랑을 할 수 있는 사람은 인격적으로 성숙한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":30,"end":35,"before":"미성숙한 ","after":"성숙한 "}]},"성숙한 사람은 남에게 의지하려는 마음을 더 키운 사람이다.":{"reason":"성숙한 사람은 남에게 의지하려는 마음을 이겨 낸 사람이다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":22,"end":27,"before":"더 키운 ","after":"이겨 낸 "}]},"나르시시즘은 다른 사람의 개성을 존중하는 모습이다. 성숙한 사람은 이런 모습을 갖추어야 한다.":{"reason":"나르시시즘은 자기 자신에게만 빠져 있는 모습이다. 성숙한 사람은 이런 모습에서 벗어나야 한다.\n근거: “인격적으로 성숙한 인간이란 타인에게 의존하고 싶어 하는 성향, 자신에게만 빠져 있는 나르시시즘, 타인을 착취하려는 욕망을 극복한 사람이다.”\n12문단에서 확인할 수 있어요.","edits":[{"start":7,"end":23,"before":"다른 사람의 개성을 존중하는 ","after":"자기 자신에게만 빠져 있는 "},{"start":40,"end":49,"before":"모습을 갖추어야 ","after":"모습에서 벗어나야 "}]}},"pageSpecificReasons":true,"editorSourceVersion":"186322a0c3f3057780ce937cab95b5880cae690f0eaecb630a68e5ad372fd623"}]}]};})(window);
